package runar

// N-296: cross-tier rule for an explicit Sig in a merge's per-input args
// (AdditionalContractInputArgs): a Sig slot the primary call left auto-signed
// (nil) is ALWAYS signed by the connected signer for each additional contract
// input; a caller-supplied value in that slot is overwritten (TS reference).
//
// Proves: on the inputs of conformance/sdk-call/stateful-merge-prepared.json,
// Call with (a) no per-input args and (b) an explicit garbage Sig in the
// per-input args broadcasts a tx byte-equal to n296ReferenceTxHex (derived by
// the TS SDK, Spend-validated on all three inputs by its MockProvider).
// Does not prove: the other tiers (own tests, same constant), non-Sig slots,
// or a live node.

import (
	"encoding/json"
	"os"
	"path/filepath"
	"runtime"
	"strings"
	"testing"
)

const n296ReferenceTxHex = ""

func n296Merge(t *testing.T, perInput [][]interface{}) string {
	t.Helper()
	_, thisFile, _, _ := runtime.Caller(0)
	raw, err := os.ReadFile(filepath.Join(filepath.Dir(thisFile), "..", "..", "conformance", "sdk-call", "stateful-merge-prepared.json"))
	if err != nil {
		t.Fatalf("read vector: %v", err)
	}
	var v n286Vector
	if err := json.Unmarshal(raw, &v); err != nil {
		t.Fatalf("parse vector: %v", err)
	}
	var art RunarArtifact
	if err := json.Unmarshal(v.Artifact, &art); err != nil {
		t.Fatalf("parse artifact: %v", err)
	}
	signer, err := NewLocalSigner(v.PrivKeyHex)
	if err != nil {
		t.Fatalf("signer: %v", err)
	}
	addr, _ := signer.GetAddress()
	provider := NewMockProvider("testnet")
	provider.AddUtxo(addr, v.FundingUtxo)
	cu := v.ContractUtxo
	provider.AddContractUtxo(cu.Script, &cu)
	eu := v.ExtraContractUtxo
	provider.AddContractUtxo(eu.Script+":extra", &eu)
	c, err := FromUtxo(&art, v.ContractUtxo)
	if err != nil {
		t.Fatalf("FromUtxo: %v", err)
	}
	opts := &CallOptions{
		AdditionalContractInputs:    []*UTXO{&eu},
		NewState:                    map[string]interface{}{"count": int64(1)},
		AdditionalContractInputArgs: perInput,
	}
	if _, _, err := c.Call(v.Method, []interface{}{nil}, provider, signer, opts); err != nil {
		t.Fatalf("Call: %v", err)
	}
	txs := provider.GetBroadcastedTxs()
	if len(txs) != 1 {
		t.Fatalf("expected 1 broadcast, got %d", len(txs))
	}
	return txs[0]
}

func TestN296_MergeDefaultPath_MatchesReference(t *testing.T) {
	if got := n296Merge(t, nil); got != n296ReferenceTxHex {
		t.Fatalf("default-path merge tx differs from the TS reference:\n got %s\nwant %s", got, n296ReferenceTxHex)
	}
}

func TestN296_MergeExplicitSigIsOverwrittenBySigner(t *testing.T) {
	got := n296Merge(t, [][]interface{}{{strings.Repeat("ab", 71)}})
	if got != n296ReferenceTxHex {
		t.Fatalf("explicit-Sig merge tx differs from the TS reference:\n got %s\nwant %s", got, n296ReferenceTxHex)
	}
}
